parameters.jsCode:
// Deterministic validation (legacy gap G3): the missing-field flagging the website
// promises for Module 1. Intentionally code, not the LLM, so it is predictable and testable.
// Also fixes bug B1 by standardizing snake_case keys end-to-end (no 'cantidad' mismatch).
//
// Two per-request routing fields are normalized here too (Phase 7):
//  - request_type: pricing_only | proposal_only | full_pipeline | unspecified.
//  - scope_of_supply: which scope items apply to THIS request. The LLM returns true/false/null;
//    null ('not stated') is resolved to the catalog default below. Source of truth for the
//    catalog + defaults: schemas/scope-catalog.json (keep this map in sync with that file).
const SCOPE_DEFAULTS = {
  materials: true, engineering: true, installation: false, commissioning: false,
  project_management: false, spare_parts: false, shipping: false, training: false, warranty: true
};

const trigger = $('Execute Workflow Trigger').first().json;
const extracted = ($input.first().json.output) || {};

const client = extracted.client || {};
const project = extracted.project || {};
const reqs = Array.isArray(extracted.technical_requirements) ? extracted.technical_requirements : [];

// Normalize request_type.
const RT = ['pricing_only', 'proposal_only', 'full_pipeline'];
const request_type = RT.includes(extracted.request_type) ? extracted.request_type : 'unspecified';

// Normalize scope_of_supply against the catalog defaults (null/undefined -> default).
// The Information Extractor returns booleans as STRINGS, and not always 'true'/'false' -
// it has also drifted to 'yes'/'no'/'included'/'excluded'. Coerce all known variants.
const rawScope = extracted.scope_of_supply || {};
function toBool(v){ if(v===true) return true; if(v===false) return false; if(typeof v==='string'){ const s=v.trim().toLowerCase(); if(s==='true'||s==='yes'||s==='included'||s==='y'||s==='1') return true; if(s==='false'||s==='no'||s==='excluded'||s==='n'||s==='0') return false; } return null; }
const scope_of_supply = {};
for (const k of Object.keys(SCOPE_DEFAULTS)) {
  const b = toBool(rawScope[k]);
  scope_of_supply[k] = (b === null) ? SCOPE_DEFAULTS[k] : b;
}

// Required-field set depends on what we must produce. A price estimate needs less than a
// full written proposal. 'unspecified' is validated strictly (treated like full_pipeline).
const pricingOnly = request_type === 'pricing_only';
const missing = [];
if (!client.company) missing.push('client.company');
if (reqs.length === 0) missing.push('technical_requirements');
if (!pricingOnly) {
  if (!client.contact_name) missing.push('client.contact_name');
  if (!client.email) missing.push('client.email');
  if (!project.type) missing.push('project.type');
}

const dataStatus = missing.length === 0 ? 'complete' : 'incomplete';
// Normalize language: the extractor may return 'English'/'Spanish'/'es'/'en'/'español'.
const _l = String(extracted.language || '').trim().toLowerCase();
const lang = (_l === 'es' || _l.startsWith('spa') || _l.startsWith('esp')) ? 'es' : 'en';

return [{ json: {
  client_id: trigger.client_id,
  client_config: trigger.client_config || null,
  status: 'ok',
  errors: [],
  data: {
    client: {
      company: client.company ?? null,
      contact_name: client.contact_name ?? null,
      contact_last_name: client.contact_last_name ?? null,
      email: client.email ?? null
    },
    project: {
      type: project.type ?? null,
      location: project.location ?? null,
      desired_deadline: project.desired_deadline ?? null
    },
    technical_requirements: reqs.map(r => ({
      item: r.item ?? null,
      quantity: r.quantity ?? null,
      spec: r.spec ?? null
    })),
    notes: extracted.notes ?? null,
    language: lang,
    request_type,
    scope_of_supply,
    status: dataStatus,
    missing_fields: missing
  }
} }];
